(async () => {
  const real = window.fetch.bind(window);
  window.fetch = (input, init) => {
    const url = typeof input === 'string' ? input : input.url;
    if (/\/api\/inbox(\?|$)/.test(new URL(url, location.href).pathname + (url.includes('?') ? '?' : ''))) return Promise.resolve(new Response(JSON.stringify({ error: 'The inbox could not be read.' }), { status: 500, headers: { 'content-type': 'application/json' } }));
    return real(input, init);
  };
  const inbox = await import('/src/state/inbox.ts');
  inbox.setInboxView(null);
  inbox.openInbox();
  return true;
})()
